#include <vector>

class Solution {
public:
    long long incremovableSubarrayCount(std::vector<int>& nums) {
        int n = nums.size();
        int p = 0;
        while (p + 1 < n && nums[p] < nums[p + 1]) ++p;
        if (p == n - 1) return (long long)n * (n + 1) / 2;
        int s = n - 1;
        while (s > 0 && nums[s - 1] < nums[s]) --s;
        long long ans = n - s + 1;
        int j = s;
        for (int i = 0; i <= p; ++i) {
            while (j < n && nums[j] <= nums[i]) ++j;
            ans += (n - j + 1);
        }
        return ans;
    }
};

class Solution {
    public long incremovableSubarrayCount(int[] nums) {
        int n = nums.length;
        int p = 0;
        while (p + 1 < n && nums[p] < nums[p + 1]) p++;
        if (p == n - 1) return (long long)n * (n + 1) / 2;
        int s = n - 1;
        while (s > 0 && nums[s - 1] < nums[s]) s--;
        long ans = n - s + 1;
        int j = s;
        for (int i = 0; i <= p; i++) {
            while (j < n && nums[j] <= nums[i]) j++;
            ans += (n - j + 1);
        }
        return ans;
    }
}

var incremovableSubarrayCount = function(nums) {
    const n = nums.length;
    let p = 0;
    while (p + 1 < n && nums[p] < nums[p + 1]) p++;
    if (p === n - 1) return (n * (n + 1)) / 2;
    let s = n - 1;
    while (s > 0 && nums[s - 1] < nums[s]) s--;
    let ans = n - s + 1;
    let j = s;
    for (let i = 0; i <= p; i++) {
        while (j < n && nums[j] <= nums[i]) j++;
        ans += (n - j + 1);
    }
    return ans;
};
